} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  BILLING_GRADE_MIX,
  HEADLINE,
  HOSPITAL_PANEL,
  PEER_COMPARE,
  REGION_SUMMARY,
  SOURCE_NOTE,
  STATE_LADDER,
  SUIT_BAND_MIX,
  VINTAGE_PATH,
  fmtInt,
  fmtMoneyM,
  fmtPct,
  fmtRatio,
  hospitalsByPeer,
  hospitalsByRegion,
  intensityLadder,
  type PeerTier,
  type RegionId,
  type SuitBand,
} from "@/data/hospital-charity-care-versus-collection-suits-2026-data";

// viz-types: intensity ladder bars, charity??suits scatter, vintage
// area+line, suit-band pie + peer bars, region stacks, billing grades
// | layout: default
// smoke-marker: Suits per charity-care dollar

type ViewId =
  | "intensity"
  | "scatter"
  | "vintage"
  | "peers"
  | "regions"
  | "grades";

type RegionFilter = "all" | RegionId;
type PeerFilter = "all" | PeerTier;
type ScatterLens = "suits" | "intensity" | "margin";

const NAVY = "#0f172a";
const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const SLATE = "#64748b";
const INDIGO = "#4f46e5";
const SKY = "#0284c8";
const EMERALD = "#059669";

const REGION_COLORS: Record<string, string> = {
  South: ROSE,
  Midwest: TEAL,
  West: AMBER,
  Northeast: INDIGO,
};

const BAND_COLORS: Record<SuitBand, string> = {
  none: EMERALD,
  low: SKY,
  moderate: AMBER,
  aggressive: ROSE,
};

const PEER_COLORS: Record<string, string> = {
  Academic: INDIGO,
  Community: TEAL,
  "Safety-net": EMERALD,
  "System flagship": AMBER,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  options,
  value,
  onChange,
}: {
  options: { id: T; label: string }[];
  value: T;
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap gap-2">
      {options.map((o) => (
        <button
          key={o.id}
          type="button"
          onClick={() => onChange(o.id)}
          className={`rounded-lg px-3 py-1.5 text-sm font-medium transition-colors ${
            value === o.id
              ? "bg-slate-900 text-white"
              : "bg-slate-100 text-slate-700 hover:bg-slate-200"
          }`}
        >
          {o.label}
        </button>
      ))}
    </div>
  );
}

