                      />
                    ))}
                  </Bar>
                  <Bar
                    dataKey="medianCharityPct"
                    name="Median charity %"
                    fill={SLATE}
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="State intensity ladder"
            subtitle="Panel states ranked by suits per $1M charity care"
          >
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={stateRows}
