  billingGrade: "A" | "B" | "C" | "D" | "F";
  suitBand: SuitBand;
  confidence: Confidence;
};

function band(suits: number): SuitBand {
  if (suits <= 2) return "none";
  if (suits <= 24) return "low";
  if (suits <= 99) return "moderate";
  return "aggressive";
