export type RegionId =
  | "South"
  | "Midwest"
  | "Northeast"
  | "West";

export type PeerTier =
  | "Academic"
  | "Community"
  | "Safety-net"
  | "System flagship";

export type SuitBand = "none" | "low" | "moderate" | "aggressive";

